add_action( 'admin_menu', 'perfectpixel_remove_payments_menu', 999 );

function perfectpixel_remove_payments_menu() {
	global $menu;
	if ( ! is_array( $menu ) ) {
		return;
	}
	foreach ( $menu as $item ) {
		$slug = isset( $item[2] ) ? (string) $item[2] : '';
		foreach ( array( 'PAYMENTS_MENU_ITEM', 'wc-settings&tab=checkout', 'wc-pay-welcome-page', 'task=payments' ) as $marker ) {
			if ( false !== strpos( $slug, $marker ) ) {
				remove_menu_page( $slug );
				break;
			}
		}
	}
}
